    // 1. Declare inputs as regs, outputs as wires
    // 2. Instantiate TopModule dut ( ... );
    // 3. Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Apply stimulus and verify outputs
        // If an output is wrong: errors = errors + 1;
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
```

SPECIFICATION:

I would like you to implement a module named TopModule with the following
interface. All input and output ports are one bit unless otherwise
specified.

 - input  clk
 - input  reset
 - input  in
 - output out

Implement the following Moore state machine with two states, one input,
and one output. The reset state is B and reset is active-high
synchronous.

  B (out=1) --in=0--> A
  B (out=1) --in=1--> B
  A (out=0) --in=0--> B
  A (out=0) --in=1--> A



CANDIDATE RTL TO ATTACK:
```verilog
module TopModule (
    input  clk,
    input  reset,
    input  in,
    output reg out
);

    // State encoding
    typedef enum reg [1:0] {
        B = 2'b00,
        A = 2'b01
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always @(*) begin
        case (current_state)
            B: begin
                if (in == 0) begin
                    next_state = A;
                    out = 1;
                end else begin
                    next_state = B;
                    out = 1;
                end
            end
            A: begin
                if (in == 0) begin
                    next_state = B;
                    out = 0;
                end else begin
                    next_state = A;
                    out = 0;
                end
            end
            default: begin
                next_state = B;
                out = 1; // Default state output
            end
        endcase
    end

    // State update logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= B; // Reset to state B
            out <= 1;           // Output in reset state
        end else begin
            current_state <= next_state; // Update state
        end
    end

endmodule
```

